(function(outputs, steps, params, stepResult, assertEqual) {
    describe('ATF-DT-02: Machine Fleet Status & Downtime Dispatch', function() {
        var P = 'x_2056099_indust_0_';

        it('should have at least 12 operational machines in the machine table', function() {
            var mGr = new GlideRecord(P + 'machine');
            mGr.query();
            expect(mGr.getRowCount()).toBeGreaterThanOrEqual(12);
        });

        it('should detect the CNC Lathe Cell 02 bottleneck machine', function() {
            var mGr = new GlideRecord(P + 'machine');
            mGr.addQuery('number', 'CONTAINS', '02').addOrCondition('name', 'CONTAINS', 'Cell 02');
            mGr.query();
            var found = false;
            while (mGr.next()) {
                var stat = mGr.getValue('status');
                if (stat === 'maintenance_required' || stat === 'bottleneck' || stat === 'operational') {
                    found = true;
                }
            }
            expect(found).toBe(true);
        });

        it('should have a corrective maintenance order for the bottleneck machine', function() {
            var mm = new GlideRecord(P + 'mach_maint');
            mm.query();
            expect(mm.getRowCount()).toBeGreaterThanOrEqual(1);
        });

        it('should have an active downtime incident logged with root cause', function() {
            var md = new GlideRecord(P + 'mach_down');
            md.query();
            expect(md.getRowCount()).toBeGreaterThanOrEqual(1);
            if (md.next()) {
                expect(md.getValue('reason')).toContain('Spindle');
            }
        });
    });
})(outputs, steps, params, stepResult, assertEqual);
